mapper.select:
select w.copy_id, w.title, w.process_id, w.process_name, w.category_id,
       w.task_id, w.user_id, w.originator_id, w.originator_name,
       w.create_by, w.create_time, w.update_by, w.update_time, w.status
from wf_copy w
inner join act_hi_procinst e on w.instance_id = e.PROC_INST_ID_

    and w.process_name = #{processName}
    and w.originator_name =#{originatorName}
    and w.status =#{status}
    and w.user_id =#{userId}

order by w.create_time desc

select wc.copy_id AS copyId, wc.title, wc.process_id AS processId, wc.process_name AS processName, wc.category_id AS categoryId, wc.deployment_id AS deploymentId, wc.instance_id AS instanceId, wc.task_id AS taskId, wc.user_id AS userId, wc.originator_id AS originatorId, wc.originator_name AS originatorName, wc.create_time AS createTime, wc.status, wy.url, 'copy' AS noticeType, concat_ws('', wc.originator_name, '于', to_char(wc.create_time, 'yyyy-MM-dd HH24:MI:ss'), '抄送了', wc.title) AS content from wf_copy wc left join wf_category wy on wy.code = wc.category_id
AND wy.code = #{params.category}
AND wc.create_time >= #{params.beginTime}
AND wc.create_time <= #{params.endTime}
and wc.user_id = #{userId}
and ( wc.originator_name like '%' || #{params.keyWord} || '%' or wc.title like '%' || #{params.keyWord} || '%' )
order by wc.create_time desc
